import json

with open('results/mvp/analysis/consensus/consensus_classification.json') as f:
    consensus = json.load(f)
with open('results/method_ablation_phase2_panel.json') as f:
    panel = json.load(f)

methods_list = ['naive', 'differenced', 'threshold', 'permutation_granger', 'TY']

null_pairs = []
for pv in panel['pair_verdicts']:
    if pv['alpha'] == 0.0:
        verdicts = [pv[m]['verdict'] for m in methods_list]
        null_pairs.append({'pair': f"{pv['canary']}->{pv['downstream']}", 'verdicts': verdicts, 'n_sig': sum(verdicts)})

fpr_data = []
for K in range(1, 6):
    sig_pairs = [p for p in null_pairs if p['n_sig'] >= K]
    methods_detail = {}
    for i, m in enumerate(methods_list):
        methods_detail[m] = sum(1 for p in null_pairs if p['verdicts'][i])
    fpr_data.append({
        'method_threshold': K, 'sig_pairs': len(sig_pairs), 'total': 8,
        'fpr': round(len(sig_pairs) / 8, 4),
        'sig_pair_labels': [p['pair'] for p in sig_pairs],
        'methods_detail': methods_detail
    })

pair_labels = [c['pair_label'] for c in consensus['classifications']]
seed_counts = [c['seed_counts'] for c in consensus['classifications']]
robust_6_indices = {c['pair_index'] for c in consensus['classifications'] if c['is_robust']}
robust_6_labels = [pair_labels[i] for i in sorted(robust_6_indices)]

fnr_rows = []
for K in range(1, 6):
    for S in range(1, 5):
        robust_indices = []
        for idx, sc in enumerate(seed_counts):
            if sum(1 for s in sc if s >= S) >= K:
                robust_indices.append(idx)
        robust_count_16 = len(robust_indices)
        robust_in_6 = len([i for i in robust_indices if i in robust_6_indices])
        fnr_rows.append({
            'method_threshold': K, 'seed_threshold': S,
            'robust_count_of_16': robust_count_16,
            'fnr_all_16': round((16 - robust_count_16) / 16, 4),
            'robust_count_of_6': robust_in_6,
            'fnr_robust_6': round((6 - robust_in_6) / 6, 4),
            'robust_pairs': [pair_labels[i] for i in robust_indices]
        })

output = {
    'calibration_version': 'v1',
    'date': '2026-05-15',
    'fpr_table': {
        'description': 'FPR at alpha=0.0 null control (seed=42 only, 8 pairs)',
        'note': 'Single seed — seed_threshold dimension N/A for FPR. Only method_threshold varies.',
        'method_thresholds': [1, 2, 3, 4, 5],
        'methods_order': ['naive_pearson', 'differenced_xcorr', 'threshold_onset', 'permutation_granger', 'toda_yamamoto'],
        'null_control_pairs': [p['pair'] for p in null_pairs],
        'data': fpr_data
    },
    'fnr_table': {
        'description': 'FNR at alpha=1.0 (4 seeds, 16 pairs, 6 robust ground truth)',
        'ground_truth_robust_6': robust_6_labels,
        'note': 'Ground truth positive = 6 pairs classified ROBUST at default (4/5 methods, 3/4 seeds). FNR_all_16 treats all 16 alpha=1.0 pairs as positives.',
        'rows': fnr_rows
    },
    'recommended_config': {
        'method_threshold': 4,
        'seed_threshold': 3,
        'rationale': 'FPR=0.0 (no false positives at alpha=0.0), FNR_robust=0.0 (all 6 confirmed ROBUST pairs detected). Achieves perfect separation on available data. Lowering to 3/5 methods inflates detections from 6 to 8 (adds token_entropy→perplexity, ece→perplexity) while FPR rises to 0.375.'
    },
    'practical_guidance': [
        {'config': '1/5 methods, 1/4 seeds', 'fpr': 1.0, 'fnr_all_16': 0.0, 'fnr_robust_6': 0.0, 'use_case': 'Exploratory screening'},
        {'config': '3/5 methods, 2/4 seeds', 'fpr': 0.375, 'fnr_all_16': 0.4375, 'fnr_robust_6': 0.0, 'use_case': 'Standard analysis'},
        {'config': '4/5 methods, 3/4 seeds', 'fpr': 0.0, 'fnr_all_16': 0.625, 'fnr_robust_6': 0.0, 'use_case': 'Publication-grade (our default)'},
        {'config': '5/5 methods, 4/4 seeds', 'fpr': 0.0, 'fnr_all_16': 0.875, 'fnr_robust_6': 0.6667, 'use_case': 'Conservative / safety-critical'}
    ]
}

with open('/tmp/fpr_fnr_calibration.json', 'w') as f:
    json.dump(output, f, indent=2, ensure_ascii=False)
print("Written to /tmp/fpr_fnr_calibration.json")
print(f"File size: {len(json.dumps(output, indent=2, ensure_ascii=False))} chars")
